INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000242',
  'a1000001-0001-4000-8000-000000000104',
  'ex-4-2-l1-translation-fix',
  'Exercise 4.2 - L1 Direct-Translation Fix',
  'correction',
  'Each sentence contains a preposition error caused by direct translation from Bangla. Rewrite each one correctly.',
  $items2$[{"id": "q1", "prompt": "According to me, the government should act quickly.", "answer": "In my opinion, the government should act quickly.", "accepted": ["In my opinion, the government should act quickly.", "I think the government should act quickly."], "reason": "Use in my opinion, not according to me.", "bn_note": null}, {"id": "q2", "prompt": "We discussed about the new policy for an hour.", "answer": "We discussed the new policy for an hour.", "accepted": ["We discussed the new policy for an hour."], "reason": "discuss takes a direct object -- no about.", "bn_note": null}, {"id": "q3", "prompt": "He entered into the classroom without knocking.", "answer": "He entered the classroom without knocking.", "accepted": ["He entered the classroom without knocking."], "reason": "enter + object; into not needed.", "bn_note": null}, {"id": "q4", "prompt": "The teacher emphasised on the importance of grammar.", "answer": "The teacher emphasised the importance of grammar.", "accepted": ["The teacher emphasised the importance of grammar.", "The teacher put emphasis on the importance of grammar."], "reason": "emphasise takes a direct object.", "bn_note": null}, {"id": "q5", "prompt": "After the trip, they returned back to their village.", "answer": "After the trip, they returned to their village.", "accepted": ["After the trip, they returned to their village."], "reason": "return already means go back -- no back.", "bn_note": null}, {"id": "q6", "prompt": "The report comprises of five main sections.", "answer": "The report comprises five main sections.", "accepted": ["The report comprises five main sections.", "The report is composed of five main sections."], "reason": "comprise takes no of (or use be composed of).", "bn_note": null}, {"id": "q7", "prompt": "She married with a doctor last year.", "answer": "She married a doctor last year.", "accepted": ["She married a doctor last year."], "reason": "marry takes a direct object.", "bn_note": null}, {"id": "q8", "prompt": "I want to request to you for some help.", "answer": "I want to request some help from you. / I want to ask you for some help.", "accepted": ["I want to request some help from you.", "I want to ask you for some help."], "reason": "request + object; not request to someone.", "bn_note": null}, {"id": "q9", "prompt": "The essay mentioned about three possible solutions.", "answer": "The essay mentioned three possible solutions.", "accepted": ["The essay mentioned three possible solutions."], "reason": "mention + object -- no about.", "bn_note": null}, {"id": "q10", "prompt": "The researchers investigated about the causes of pollution.", "answer": "The researchers investigated the causes of pollution.", "accepted": ["The researchers investigated the causes of pollution."], "reason": "investigate + object -- no about.", "bn_note": null}, {"id": "q11", "prompt": "We must cope up with the rising cost of living.", "answer": "We must cope with the rising cost of living.", "accepted": ["We must cope with the rising cost of living."], "reason": "cope with -- no up.", "bn_note": null}, {"id": "q12", "prompt": "The minister reached to the venue an hour late.", "answer": "The minister reached the venue an hour late.", "accepted": ["The minister reached the venue an hour late."], "reason": "reach + object -- no to.", "bn_note": null}, {"id": "q13", "prompt": "My opinion is different than yours on this matter.", "answer": "My opinion is different from yours on this matter.", "accepted": ["My opinion is different from yours on this matter."], "reason": "different from (standard).", "bn_note": null}, {"id": "q14", "prompt": "Students should concentrate in their studies.", "answer": "Students should concentrate on their studies.", "accepted": ["Students should concentrate on their studies."], "reason": "concentrate on.", "bn_note": null}, {"id": "q15", "prompt": "The country is suffering with severe traffic congestion.", "answer": "The country is suffering from severe traffic congestion.", "accepted": ["The country is suffering from severe traffic congestion."], "reason": "suffer from.", "bn_note": null}]$items2$::jsonb,
  2,
  true
)
